import {defineConfig} from 'vite';
import {resolve} from 'path';
import {mionVitePlugin} from '@mionjs/devtools/vite';

// Server build config. The batch transport is generated by THIS build: the resolver reads every
// `batch([...])` and inline inputFrom mapper out of the client project named below, writes the
// batch table and the mapper modules under this project's `.mion/rpc/`, and imports the table from
// the module that calls createMionRouter. Leave `client` out when client and server share one
// project.
export default defineConfig({
  plugins: [
    mionVitePlugin({
      runTypes: {tsConfig: resolve(__dirname, 'tsconfig.json')},
      client: {tsConfig: resolve(__dirname, '../client/tsconfig.json')},
    }),
  ],
  build: {
    lib: {
      entry: resolve(__dirname, 'src/init.ts'),
      formats: ['es'],
    },
    rollupOptions: {
      external: [/^[^./]/],
    },
  },
});
